import {formatDebtAmount,formatDebtTotals} from './debt-currency.mjs';
import {t} from './i18n.mjs';
import {translateAdminError} from './admin-errors.mjs';
import {initAdvertisingAdmin} from './advertising-admin.mjs';
import {initFraudMonitoring} from './fraud-monitoring.mjs';
import {publicCard} from './card-model.mjs';
const root=document.querySelector('#management-root'),admin=document.body.dataset.management==='admin';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={pending:t("Pending review","Chờ duyệt","검토 대기"),approved:t("Approved","Đã duyệt","승인됨"),rejected:t('Rejected','Từ chối','반려됨')};
let members=[],section='cards';
let user=null,status='pending',cards=[],selected=null,challenge=null,loginEmail='',busy=false,resendAt=0;
async function call(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error ? translateAdminError(result.error) : t("Could not connect to the server.","Không thể kết nối máy chủ.","서버에 연결할 수 없습니다.")),{status:response.status});return result;}
const advertisingAdmin=initAdvertisingAdmin({root,call,back:()=>load().catch(error=>notice(error.message))});
const fraudMonitoring=initFraudMonitoring({root,call,back:()=>load().catch(error=>notice(error.message))});
function notice(message){let element=document.querySelector('#management-notice');if(!element){element=document.createElement('p');element.id='management-notice';element.setAttribute('role','alert');root.prepend(element);}element.textContent=message;}
async function boot(){try{user=(await call(admin?'admin/me':'auth/me')).user;if(section==='members'&&user.isOwner)await loadMembers();else await load();}catch(error){if(error.status===401)login();else if(error.status===403)denied();else notice(error.message);}}
function denied(){root.innerHTML=`<section class="login-panel"><span class="eyebrow">${t("ADMIN ACCESS","KHU VỰC QUẢN TRỊ","관리자 전용")}</span><h1>${t("Access denied","Không có quyền truy cập","접근 권한이 없습니다")}</h1><p>${t("Sign in with an email address that has administrator access.","Tài khoản hiện tại không phải admin. Đăng nhập bằng email admin đã được cấu hình trên máy chủ.","관리자 권한이 있는 이메일 주소로 로그인하세요.")}</p><button id="switch-account">${t("Sign in with another account","Đăng nhập tài khoản khác","다른 계정으로 로그인")}</button></section>`;document.querySelector('#switch-account').onclick=async()=>{try{await call('auth/logout',{});login();}catch(error){notice(error.message);}};}
function login(){root.innerHTML=`<section class="login-panel"><span class="eyebrow">${admin?t("ADMIN ACCESS","ADMIN ACCESS","관리자 전용"):t("YOUR DEBT CARDS","THẺ CỦA BẠN","내 채무 카드")}</span><h1>${challenge?t("Verify your email","Xác nhận email","이메일 인증"):t("Sign in with email","Đăng nhập bằng email","이메일로 로그인")}</h1><p>${challenge?t(`Enter the six-digit code sent to ${e(loginEmail)}.`,`Nhập mã 6 số đã gửi đến ${e(loginEmail)}.`,`${e(loginEmail)} 주소로 보낸 6자리 코드를 입력하세요.`):t("Use the email address you registered in the app. If you need an account, sign up in the app first.","Sử dụng tài khoản email đã đăng ký trên app. Nếu chưa có tài khoản, hãy đăng ký trong ứng dụng trước.","앱에 등록한 이메일 주소를 사용하세요. 계정이 없다면 앱에서 먼저 가입하세요.")}</p><form id="management-login">${challenge?`<label for="login-code">${t("Verification code","Mã xác nhận","인증 코드")}</label><input id="login-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required>`:`<label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="email" value="${e(loginEmail)}" required>`}<p id="login-error" role="alert"></p><button>${challenge?t("Verify","Xác nhận","인증하기"):t("Send sign-in code","Gửi mã đăng nhập","로그인 코드 보내기")}</button></form>${challenge?`<button class="secondary" id="restart-login">${t("Change email address","Đổi email","이메일 주소 변경")}</button>`:''}<a href="/">${t("Back to the app","Về ứng dụng","앱으로 돌아가기")}</a></section>`;document.querySelector('#restart-login')?.addEventListener('click',()=>{challenge=null;login();});document.querySelector('#management-login').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const button=event.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(event.target));if(challenge){await call('auth/verify-code',{id:challenge.id,code:data.code});challenge=null;await boot();}else{if(Date.now()<resendAt)throw Error(t("Wait 60 seconds before requesting a new code.","Vui lòng đợi 60 giây trước khi yêu cầu mã mới.","새 코드를 요청하려면 60초 후에 다시 시도하세요."));loginEmail=data.email.trim();challenge=await call('auth/request-code',{purpose:'login',email:loginEmail});resendAt=Date.now()+60000;login();}}catch(error){const el=document.querySelector('#login-error');if(el)el.textContent=error.message;else notice(error.message);}finally{busy=false;if(button.isConnected)button.disabled=false;}};}
async function load(){const result=await call(admin?'admin/cards?status='+status:'cards/mine');cards=result.cards;selected=null;render();}
function render(){section='cards';const shown=admin?cards:cards.filter(c=>c.status===status);root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">${admin?t("ADMIN WORKSPACE","ADMIN WORKSPACE","관리자 작업 공간"):t("YOUR DEBT CARDS","YOUR DEBT CARDS","내 채무 카드")}</span><h1>${admin?t("Review debt cards","Duyệt thẻ báo nợ","채무 카드 검토"):t("Submitted cards","Thẻ đã gửi","제출한 카드")}</h1><p>${admin?t("Read each story and verify the details before approving it for publication.","Đọc câu chuyện, kiểm tra thông tin và quyết định trước khi công khai.","카드를 공개하기 전에 사연과 세부 정보를 확인하세요."):t("Track your review results. Cards appear in Discover only after approval.","Theo dõi kết quả xét duyệt. Thẻ chờ duyệt hoặc bị từ chối sẽ không xuất hiện ở trang quẹt.","검토 결과를 확인하세요. 승인된 카드만 둘러보기에 표시됩니다.")}</p></div><div class="management-account"><span>${e(user.email||user.name)}</span>${admin?`<button id="advertising-admin" class="secondary">${t("Manage ads","Quản lý quảng cáo","광고 관리")}</button><button id="fraud-monitoring" class="secondary">${t("Fraud monitoring","Fraud Monitoring","이상 활동 모니터링")}</button>`:''}${admin&&user.isOwner?`<button id="manage-admins" class="secondary">${t("Manage admins","Quản lý admin","관리자 관리")}</button>`:''}<button id="refresh" class="secondary">${t("↻ Refresh","↻ Tải lại","↻ 새로고침")}</button>${admin?`<button id="logout" class="secondary">${t("Sign out","Đăng xuất","로그아웃")}</button>`:''}</div></section><nav class="status-tabs" aria-label="${t("Card status","Trạng thái thẻ","카드 상태")}">${Object.entries(labels).map(([key,label])=>`<button data-status="${key}" aria-pressed="${key===status}">${label}${!admin?` <span>${cards.filter(c=>c.status===key).length}</span>`:''}</button>`).join('')}</nav><div class="management-grid"><section class="submission-list" aria-label="${t("Card list","Danh sách thẻ","카드 목록")}">${shown.length?shown.map(c=>`<button class="submission-summary" data-card="${e(c.id)}"><span class="status-badge ${c.status}">${labels[c.status]}</span><h2>${e(c.debts[0].title)}</h2><strong>${formatDebtTotals(c.debts)}</strong><p>${t(c.debts.length===1?"1 debt item":`${c.debts.length} debt items`,`${c.debts.length} khoản nợ`,`채무 ${c.debts.length}건`)} · ${e(new Date(c.createdAt).toLocaleString(t('en-AU','vi-VN','ko-KR')))}</p>${admin?`<small>${e(c.identity.name)} · ${e(c.identity.email)}</small>`:''}${c.reason?`<p class="rejection-reason">${t("Reason: ","Lý do: ","사유: ")}${e(c.reason)}</p>`:''}<span class="open-card">${t("View card →","Xem thẻ →","카드 보기 →")}</span></button>`).join(''):`<div class="management-empty"><span>♧</span><h2>${t("No cards in this section","Chưa có thẻ trong mục này","이 항목에 카드가 없습니다")}</h2><p>${t("New submissions appear under Pending review.","Thẻ mới gửi sẽ xuất hiện trong mục Chờ duyệt.","새로 제출된 카드는 검토 대기에 표시됩니다.")}</p></div>`}</section><section id="review-panel" class="review-panel"><div class="review-placeholder"><span>▤</span><h2>${t("Select a card to view","Chọn một thẻ để xem","볼 카드를 선택하세요")}</h2><p>${admin?t("Only the card owner and admins can see the full submission.","Nội dung đầy đủ chỉ hiển thị cho chủ thẻ và admin.","카드 소유자와 관리자만 제출한 내용을 모두 볼 수 있습니다."):t("Review your submission and its status.","Xem lại nội dung và trạng thái xét duyệt của bạn.","제출한 내용과 검토 상태를 확인하세요.")}</p></div></section></div><p id="management-notice" role="alert"></p>`;
 root.querySelectorAll('[data-status]').forEach(button=>button.onclick=async()=>{if(busy)return;status=button.dataset.status;try{if(admin)await load();else render();}catch(error){notice(error.message);}});
 root.querySelectorAll('[data-card]').forEach(button=>button.onclick=()=>{if(!busy)show(cards.find(c=>c.id===button.dataset.card));});
 document.querySelector('#advertising-admin')?.addEventListener('click',()=>{if(!busy)advertisingAdmin.show();});
 document.querySelector('#fraud-monitoring')?.addEventListener('click',()=>{if(!busy)fraudMonitoring.show();});
 document.querySelector('#manage-admins')?.addEventListener('click',async()=>{if(busy)return;try{await loadMembers();}catch(error){notice(error.message);}});
 document.querySelector('#refresh').onclick=async()=>{if(busy)return;try{await load();}catch(error){notice(error.message);}};
 document.querySelector('#logout')?.addEventListener('click',async()=>{try{await call('auth/logout',{});user=null;login();}catch(error){notice(error.message);}});
}
function show(card){selected=card;root.querySelectorAll('[data-card]').forEach(b=>b.classList.toggle('selected',b.dataset.card===card.id));const projected=publicCard(card.debts,card.privacy,card.identity);const publicName=(card.privacy.realName&&card.identity.name)||card.identity.nickname||t("Anonymous Broke member","Broke ẩn danh","익명 Broke 회원");document.querySelector('#review-panel').innerHTML=`<div class="review-heading"><span class="status-badge ${card.status}">${labels[card.status]}</span><small>#${e(card.id.slice(0,8))}</small></div><h2>${e(card.identity.name)}</h2><p class="private-label">${t("Private information · ","Thông tin riêng tư · ","비공개 정보 · ")}${e(card.identity.email)}</p><div class="review-debts">${card.debts.map((d,i)=>`<article><span class="eyebrow">${t("DEBT ","KHOẢN NỢ ","채무 ")}${i+1}</span><h3>${e(d.title)}</h3><strong>${formatDebtAmount(d.amount,d.currency)}</strong><p class="story">${e(d.story)}</p></article>`).join('')}</div><section class="public-preview"><span class="eyebrow">${t("PUBLIC PREVIEW","BẢN HIỂN THỊ CÔNG KHAI","공개 미리보기")}</span><h3>${e(publicName)}${projected.age?`, ${e(projected.age)}`:''}</h3>${projected.location?`<p>${e(projected.location)}</p>`:''}${projected.photo?`<img class="review-photo" src="${e(projected.photo)}" alt="${t("Public profile photo","Ảnh đại diện công khai","공개 프로필 사진")}">`:''}${projected.debts.map(d=>`<h4>${e(d.title)}</h4><strong>${formatDebtAmount(d.amount,d.currency)}</strong>${d.story?`<p class="story">${e(d.story)}</p>`:''}`).join('')}<p class="privacy-note">${Object.entries({realName:t("Real name","Tên thật","실명"),age:t("Age","Tuổi","나이"),location:t("Location","Địa điểm","지역"),photo:t("Photo","Ảnh","사진"),publicStory:t("Story","Câu chuyện","사연")}).map(([key,label])=>`${label}: ${card.privacy[key]?t("On","On","켜짐"):t("Off","Off","꺼짐")}`).join(' · ')}</p></section>${card.reason?`<p class="rejection-reason">${t("Rejection reason: ","Lý do từ chối: ","반려 사유: ")}${e(card.reason)}</p>`:''}${admin&&card.status==='pending'?`<form id="review-form"><label for="review-reason">${t("Notes or rejection reason","Ghi chú / lý do từ chối","메모 또는 반려 사유")}</label><textarea id="review-reason" name="reason" maxlength="1000" placeholder="${t("Required when rejecting a card. The card owner will see this reason.","Bắt buộc khi từ chối. Chủ thẻ sẽ nhìn thấy lý do này.","반려할 때 필수입니다. 카드 소유자가 이 사유를 볼 수 있습니다.")}"></textarea><label class="approve-confirm"><input id="review-confirm" type="checkbox">${t("I have checked the submission and its public preview.","Tôi đã kiểm tra nội dung và bản hiển thị công khai.","제출 내용과 공개 미리보기를 확인했습니다.")}</label><div class="review-actions"><button class="secondary reject" type="submit" name="decision" value="rejected">${t("Reject","Từ chối","반려")}</button><button type="submit" name="decision" value="approved">${t("✓ Approve and publish","✓ Duyệt & công khai","✓ 승인 및 공개")}</button></div><p id="review-error" role="alert"></p></form>`:''}`;
 document.querySelector('#review-form')?.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const decision=event.submitter?.value,reason=document.querySelector('#review-reason').value.trim(),error=document.querySelector('#review-error');if(decision==='approved'&&!document.querySelector('#review-confirm').checked){error.textContent=t("Confirm that you have reviewed the card before approving it.","Hãy xác nhận đã kiểm tra thẻ trước khi duyệt.","승인하기 전에 카드를 검토했는지 확인하세요.");return;}if(decision==='rejected'&&!reason){error.textContent=t("Enter a reason for rejecting this card.","Vui lòng nhập lý do từ chối.","카드를 반려하는 사유를 입력하세요.");return;}busy=true;event.target.querySelectorAll('button').forEach(b=>b.disabled=true);try{await call('admin/cards/'+encodeURIComponent(selected.id)+'/review',{decision,reason});await load();notice(decision==='approved'?t("Approved. The card can now appear in Discover.","Đã duyệt. Thẻ có thể xuất hiện trong trang quẹt.","승인했습니다. 이제 둘러보기에 카드가 표시될 수 있습니다."):t("Rejected. The card owner can see the reason.","Đã từ chối. Chủ thẻ có thể xem lý do.","반려했습니다. 카드 소유자가 사유를 볼 수 있습니다."));}catch(err){if(error.isConnected)error.textContent=err.message;else notice(err.message);event.target.querySelectorAll('button').forEach(b=>b.disabled=false);}finally{busy=false;}});
}
boot();

async function loadMembers(){const result=await call('admin/members');members=result.members;section='members';renderMembers();}
function renderMembers(){
 root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">${t("OWNER WORKSPACE","OWNER WORKSPACE","소유자 작업 공간")}</span><h1>${t("Manage admins","Quản lý admin","관리자 관리")}</h1><p>${t("Grant card review access to others who manage DebtFreeLately.","Cấp quyền duyệt thẻ cho người cùng quản lý DebtFreeLately.","DebtFreeLately를 함께 운영하는 사람에게 카드 검토 권한을 부여하세요.")}</p></div><button id="back-to-cards" class="secondary">${t("← Review cards","← Duyệt thẻ","← 카드 검토")}</button></section><div class="members-layout"><section class="member-add-panel"><h2>${t("Add an admin","Thêm thành viên admin","관리자 추가")}</h2><p>${t("Admins can read private card submissions and approve or reject them. Only the owner can grant or revoke admin access.","Admin được thêm có thể đọc nội dung riêng tư của thẻ đã gửi và duyệt hoặc từ chối thẻ. Chỉ chủ sở hữu được cấp hoặc thu hồi quyền admin.","관리자는 제출된 카드의 비공개 내용을 읽고 카드를 승인하거나 반려할 수 있습니다. 소유자만 관리자 권한을 부여하거나 해제할 수 있습니다.")}</p><form id="member-add"><label for="member-email">${t("Member email address","Email thành viên","회원 이메일 주소")}</label><input id="member-email" name="email" type="email" autocomplete="off" maxlength="254" placeholder="${t("member@example.com","thanhvien@example.com","member@example.com")}" required><p class="member-help">${t("The member must register and verify this email address before signing in to the admin page. Invitations are sent separately.","Thành viên cần đăng ký tài khoản bằng đúng email này, xác minh email rồi đăng nhập trang admin. Không gửi email mời tự động.","회원은 이 이메일 주소로 가입하고 인증한 후 관리자 페이지에 로그인해야 합니다. 초대 이메일은 자동으로 발송되지 않습니다.")}</p><button>${t("Grant admin access","Cấp quyền admin","관리자 권한 부여")}</button></form></section><section class="member-list-panel"><h2>${t("Administrators ","Thành viên quản trị ","관리자 목록 ")}<span>${members.length}</span></h2><ul class="member-list">${members.map(member=>`<li><div><strong>${e(member.email)}</strong><span class="member-role">${member.role==='owner'?t("Owner","Chủ sở hữu","소유자"):t("Admin · Card review","Admin · Duyệt thẻ","관리자 · 카드 검토")}</span></div>${member.role==='owner'?`<span class="owner-protected">${t("Protected","Được bảo vệ","보호됨")}</span>`:`<button class="secondary" data-revoke="${e(member.email)}">${t("Revoke access","Thu hồi quyền","권한 해제")}</button>`}</li>`).join('')}</ul></section></div><p id="management-notice" role="alert"></p>`;
 document.querySelector('#back-to-cards').onclick=async()=>{if(busy)return;try{await load();}catch(error){notice(error.message);}};
 document.querySelector('#member-add').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const email=document.querySelector('#member-email').value.trim();event.target.querySelector('button').disabled=true;try{members=(await call('admin/members',{email})).members;renderMembers();notice(t(`Granted admin access to ${email}.`,`Đã cấp quyền admin cho ${email}.`,`${email} 계정에 관리자 권한을 부여했습니다.`));}catch(error){notice(error.message);event.target.querySelector('button').disabled=false;}finally{busy=false;}};
 root.querySelectorAll('[data-revoke]').forEach(button=>button.onclick=async()=>{if(busy)return;busy=true;button.disabled=true;const email=button.dataset.revoke;try{members=(await call('admin/members/revoke',{email})).members;renderMembers();notice(t(`Revoked admin access for ${email}.`,`Đã thu hồi quyền admin của ${email}.`,`${email} 계정의 관리자 권한을 해제했습니다.`));}catch(error){notice(error.message);button.disabled=false;}finally{busy=false;}});
}
